(7232948, 1119243, 121111, '<td valign="top">wonderful layers of flaming colors !</td>', 'wonderful layers of flaming colors !', '2014-06-25 01:28:15.000000', NULL, 1),
(7232990, 1118890, 135744, '<td valign="top">Wow very clever and well done. I love it!</td>', 'Wow very clever and well done. I love it!', '2014-06-25 03:50:39.000000', NULL, 1),
(7232994, 1119596, 114225, '<td valign="top">A bit too much saturation here. Looks radioactive.</td>', 'A bit too much saturation here. Looks radioactive.', '2014-06-25 04:33:29.000000', NULL, 1),
(7233017, 1119613, 163430, '<td valign="top">Excellent!<br/>Not the typical sun(rise/set) shot.</td>', 'Excellent!Not the typical sun(rise/set) shot.', '2014-06-25 08:07:02.000000', NULL, 1),
(7233018, 1119291, 163430, '<td valign="top">Very nice. There are lots of typical sun(rise/set) shots here and i really appreciate the ones that stand out from this crowd. The lantern is a nice touch.<br/>I would, however, prefer a bit more dramatic execution. More contrast, more vibrance in the colors and a bit darker silhouettes. Nevertheless one of my favorites in this challenge.</td>', 'Very nice. There are lots of typical sun(rise/set) shots here and i really appreciate the ones that stand out from this crowd. The lantern is a nice touch.I would, however, prefer a bit more dramatic execution. More contrast, more vibrance in the colors and a bit darker silhouettes. Nevertheless one of my favorites in this challenge.', '2014-06-25 08:12:28.000000', NULL, 1),
(7233019, 1119593, 163430, '<td valign="top">One of the best in this challenge.<br/>I love the fact that it''s not the regular beautiful landscape with pretty colors sunset shot. This one goes the extra step in telling a story.</td>', 'One of the best in this challenge.I love the fact that it''s not the regular beautiful landscape with pretty colors sunset shot. This one goes the extra step in telling a story.', '2014-06-25 08:14:27.000000', NULL, 1),
(7233020, 1119411, 163430, '<td valign="top">This concept is becoming a cliche in the last couple of challenges, but i like it. It fits my idea of an unusual sunset shot.</td>', 'This concept is becoming a cliche in the last couple of challenges, but i like it. It fits my idea of an unusual sunset shot.', '2014-06-25 08:16:11.000000', NULL, 1),
(7233021, 1119263, 163430, '<td valign="top">Hi Beau, hi Belle :-)<br/>Nice to see a sun(rise/set) shot that doesn''t feature sky and clouds.</td>', 'Hi Beau, hi Belle :-)Nice to see a sun(rise/set) shot that doesn''t feature sky and clouds.', '2014-06-25 08:18:46.000000', NULL, 1),
(7233047, 1119395, 38032, '<td valign="top">captures a nice lonesome mood.</td>', 'captures a nice lonesome mood.', '2014-06-25 09:06:31.000000', NULL, 1),
(7233048, 1118928, 38032, '<td valign="top">Wow-  so much going on here. What a splendid location! Like another planet.</td>', 'Wow-  so much going on here. What a splendid location! Like another planet.', '2014-06-25 09:07:21.000000', NULL, 1),
(7233052, 1119590, 38032, '<td valign="top">I love the subject and the family type moment. It reminds me of my own kids =)<br/> <br/>To be overly critical, what keeps it from getting a higher score from me is that the subject feels a bit distant form me. As if I''m looking down. I''d like to be closer - to be more in line with what they are seeing. More drama maybe.<br/>6</td>', 'I love the subject and the family type moment. It reminds me of my own kids =) To be overly critical, what keeps it from getting a higher score from me is that the subject feels a bit distant form me. As if I''m looking down. I''d like to be closer - to be more in line with what they are seeing. More drama maybe.6', '2014-06-25 09:21:28.000000', NULL, 1),
(7233062, 1119561, 38032, '<td valign="top">I love the textures here. Shiny, lively loveliness.</td>', 'I love the textures here. Shiny, lively loveliness.', '2014-06-25 09:47:55.000000', NULL, 1),
(7233063, 1119164, 38032, '<td valign="top">Love the grunge. Somewhere between nirvana and hell.</td>', 'Love the grunge. Somewhere between nirvana and hell.', '2014-06-25 09:48:38.000000', NULL, 1),
(7233066, 1119434, 38032, '<td valign="top">What a lovely setting. I totally want to jump on that swing. I think the colors and processing could be tamed a bit here but overall a lovely shot.</td>', 'What a lovely setting. I totally want to jump on that swing. I think the colors and processing could be tamed a bit here but overall a lovely shot.', '2014-06-25 09:50:16.000000', NULL, 1),
(7233068, 1119329, 38032, '<td valign="top">Great place. Great POV. A swimmer would really add to this =)</td>', 'Great place. Great POV. A swimmer would really add to this =)', '2014-06-25 09:53:23.000000', NULL, 1),
(7233070, 1118868, 38032, '<td valign="top">I am a fan of "screen shots" =] However, it isn''t saying much to me.</td>', 'I am a fan of "screen shots" =] However, it isn''t saying much to me.', '2014-06-25 09:56:30.000000', NULL, 1),
(7233071, 1119613, 38032, '<td valign="top">A creative take.</td>', 'A creative take.', '2014-06-25 09:57:08.000000', NULL, 1),
(7233075, 1119422, 38032, '<td valign="top">A welcome shot without a sky but with an obvious sunset. Love the vast, vicious sea juxtaposed with the innocence of childhood. I''d love to see it a bit sharper.</td>', 'A welcome shot without a sky but with an obvious sunset. Love the vast, vicious sea juxtaposed with the innocence of childhood. I''d love to see it a bit sharper.', '2014-06-25 09:59:27.000000', NULL, 1),
