(7233077, 1119143, 38032, '<td valign="top">Love the soft contrasts and earthy tones.</td>', 'Love the soft contrasts and earthy tones.', '2014-06-25 10:01:18.000000', NULL, 1),
(7233078, 1119022, 38032, '<td valign="top">Love the subject. Brings back nice memories of being on the water. 7<br/>the HDR is growing on me -  I kind of need to suspend my disbelief in the very foreground where I wonder if it should just be a bit darker to be "natural".</td>', 'Love the subject. Brings back nice memories of being on the water. 7the HDR is growing on me -  I kind of need to suspend my disbelief in the very foreground where I wonder if it should just be a bit darker to be "natural".', '2014-06-25 10:02:18.000000', NULL, 1),
