(7233302, 1119407, 138253, '<td valign="top">Very little silhouette here, which is a nice change of pace from many entries i''ve seen pop up so far (unsure total how many because i didn''t do a thumbnail view before starting on the images)<br/>I appreciate the scenery here with the emphasis on the sky above the city and the fun shapes in the clouds, while also not overcooking the image.<br/>i''m giving this a 7</td>', 'Very little silhouette here, which is a nice change of pace from many entries i''ve seen pop up so far (unsure total how many because i didn''t do a thumbnail view before starting on the images)I appreciate the scenery here with the emphasis on the sky above the city and the fun shapes in the clouds, while also not overcooking the image.i''m giving this a 7', '2014-06-25 15:42:18.000000', NULL, 1),
(7233303, 1119613, 67258, '<td valign="top">I really like this - certainly a different take on the challenge, but valid and very well photographed.</td>', 'I really like this - certainly a different take on the challenge, but valid and very well photographed.', '2014-06-25 15:43:50.000000', NULL, 1),
(7233304, 1119602, 67258, '<td valign="top">Lovely!  I definitely prefer the more subtle images, and this is amongst the best.</td>', 'Lovely!  I definitely prefer the more subtle images, and this is amongst the best.', '2014-06-25 15:44:57.000000', NULL, 1),
(7233305, 1118311, 138253, '<td valign="top">not overcooked: check<br/>not silhouette: check<br/>pleasant to look at: check<br/>score: 7  (the judges really liked the subtle tones in the sand)</td>', 'not overcooked: checknot silhouette: checkpleasant to look at: checkscore: 7  (the judges really liked the subtle tones in the sand)', '2014-06-25 15:46:40.000000', NULL, 1),
