(7234010, 1119590, 156466, '<td valign="top">Trees don''t have to be straight, but the horizon should be.  Lower the left corner a touch.</td>', 'Trees don''t have to be straight, but the horizon should be.  Lower the left corner a touch.', '2014-06-27 15:00:01.000000', NULL, 1),
(7234011, 1118868, 156466, '<td valign="top">Too crazy to give it more than a 4</td>', 'Too crazy to give it more than a 4', '2014-06-27 15:00:49.000000', NULL, 1),
(7234012, 1118841, 156466, '<td valign="top">Could be nice.  I''m just wanting to see some more or less in the shadows, and a horizon that doesn''t cut the photo in half.  6.</td>', 'Could be nice.  I''m just wanting to see some more or less in the shadows, and a horizon that doesn''t cut the photo in half.  6.', '2014-06-27 15:01:32.000000', NULL, 1),
