INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7234036, 1119434, 156466, '<td valign="top">Greens pop too much with the sun already over the horizon.  With a little desaturation and careful dodging you could still have highlighted the swing without the hot spot in the center.  Potentially 7 or 8.  Right now? 5</td>', 'Greens pop too much with the sun already over the horizon.  With a little desaturation and careful dodging you could still have highlighted the swing without the hot spot in the center.  Potentially 7 or 8.  Right now? 5', '2014-06-27 15:40:21.000000', NULL, 1),
(7234037, 1119561, 156466, '<td valign="top">There''s something overly distracting about the foreground that I want to blame on overprocessing, but I think that''s just the way it was.  Really pretty but it just doesn''t flow together for me. 7</td>', 'There''s something overly distracting about the foreground that I want to blame on overprocessing, but I think that''s just the way it was.  Really pretty but it just doesn''t flow together for me. 7', '2014-06-27 15:42:38.000000', NULL, 1),
