(7234039, 1118807, 156466, '<td valign="top">Coulda been gorgeous, but you just cooked it too long.  Structure is not always your friend.  So much potential, but I almost want to say I can name the HDR Efex Pro preset you started with.  8 that became a 5</td>', 'Coulda been gorgeous, but you just cooked it too long.  Structure is not always your friend.  So much potential, but I almost want to say I can name the HDR Efex Pro preset you started with.  8 that became a 5', '2014-06-27 15:46:03.000000', NULL, 1),
(7234041, 1119613, 156466, '<td valign="top">Nice idea, but at least get the top of the shade straight on the horizontal.  6</td>', 'Nice idea, but at least get the top of the shade straight on the horizontal.  6', '2014-06-27 15:47:52.000000', NULL, 1),
(7234042, 1119286, 156466, '<td valign="top">Could use a little less dark.</td>', 'Could use a little less dark.', '2014-06-27 15:48:17.000000', NULL, 1),
