(7235235, 1119022, 58634, '<td valign="top">Certainly stands out. Nice strong contrasted colors and beautiful silhouettes. Also, really good job on making all the textures of the boat stand out.</td>', 'Certainly stands out. Nice strong contrasted colors and beautiful silhouettes. Also, really good job on making all the textures of the boat stand out.', '2014-07-01 20:07:44.000000', NULL, 1),
(7235236, 1119576, 58634, '<td valign="top">Minimalistic, yet full of power.</td>', 'Minimalistic, yet full of power.', '2014-07-01 20:07:57.000000', NULL, 1),
(7235237, 1119611, 58634, '<td valign="top">Love the way the sun rays look. And nice catch with the bird!</td>', 'Love the way the sun rays look. And nice catch with the bird!', '2014-07-01 20:08:23.000000', NULL, 1),
(7235238, 1119124, 58634, '<td valign="top">Menacing and intimidated. Gorgeous, gorgeous, GORGEOUS shot.</td>', 'Menacing and intimidated. Gorgeous, gorgeous, GORGEOUS shot.', '2014-07-01 20:08:52.000000', NULL, 1),
(7235239, 1119528, 58634, '<td valign="top">This is just adorable! Cows are my favorite so kudos for that. I like how creative you are with this.</td>', 'This is just adorable! Cows are my favorite so kudos for that. I like how creative you are with this.', '2014-07-01 20:09:23.000000', NULL, 1),
(7235241, 1119545, 58634, '<td valign="top">I like that you were able to capture the sun right at the split of the tree branches. Sunsets and sunrises happen so quickly that you have to be prepared!</td>', 'I like that you were able to capture the sun right at the split of the tree branches. Sunsets and sunrises happen so quickly that you have to be prepared!', '2014-07-01 20:10:04.000000', NULL, 1),
(7235242, 1119181, 58634, '<td valign="top">Love the low perspective. Really beautiful.</td>', 'Love the low perspective. Really beautiful.', '2014-07-01 20:10:23.000000', NULL, 1),
(7235243, 1118296, 58634, '<td valign="top">Really beautiful image overall. My only nitpick is the fact that the tree is cut off. Kind of wish I could see it in its entirety.</td>', 'Really beautiful image overall. My only nitpick is the fact that the tree is cut off. Kind of wish I could see it in its entirety.', '2014-07-01 20:10:57.000000', NULL, 1),
